	<canvas id="myCanvas" width="500" height="500"></canvas>
	<script>
		const canvas = document.getElementById("myCanvas");
		const ctx = canvas.getContext("2d");
		const particles = [];

		// define particle class
		class Particle {
			constructor(x, y, radius, color, dx, dy) {
				this.x = x;
				this.y = y;
				this.radius = radius;
				this.color = color;
				this.dx = dx;
				this.dy = dy;
			}

			draw() {
				ctx.beginPath();
				ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
				ctx.fillStyle = this.color;
				ctx.fill();
				ctx.closePath();
			}

			update() {
				this.x += this.dx;
				this.y += this.dy;

				// handle collision with walls
				if (this.x - this.radius < 0 || this.x + this.radius > canvas.width) {
					this.dx = -this.dx;
				}

				if (this.y - this.radius < 0 || this.y + this.radius > canvas.height) {
					this.dy = -this.dy;
				}

				// handle collision with other particles
				for (let i = 0; i < particles.length; i++) {
					const otherParticle = particles[i];

					if (this === otherParticle) {
						continue;
					}

					const distance = Math.sqrt(
						Math.pow(this.x - otherParticle.x, 2) +
						Math.pow(this.y - otherParticle.y, 2)
					);

					if (distance < this.radius + otherParticle.radius) {
						const angle = Math.atan2(
							otherParticle.y - this.y,
							otherParticle.x - this.x
