						this.dy = Math.sin(angle) * Math.abs(this.dy);
						otherParticle.dx = -Math.cos(angle) * Math.abs(otherParticle.dx);
						otherParticle.dy = -Math.sin(angle) * Math.abs(otherParticle.dy);
					}
				}
			}
		}

		// create particles
		for (let i = 0; i < 50; i++) {
			const radius = Math.random() * 20 + 10;
			const x = Math.random() * (canvas.width - radius * 2) + radius;
			const y = Math.random() * (canvas.height - radius * 2) + radius;
