#include <iostream>
#include <vector>

using namespace std;

int main() {
    int M, N, Q;
    cin >> M >> N >> Q;

    vector<bool> isOnBus(N + 1, false); // mảng lưu trạng thái của từng hành khách

    int count = 0; // biến đếm số lượng người trên xe
    bool isValid = true; // biến kiểm tra xem chuỗi sự kiện có hợp lệ hay không

    for (int i = 1; i <= Q; ++i) {
        char action;
        int person;
        cin >> action >> person;

        if (action == '+') { // hành động lên xe
            if (count >= M || isOnBus[person]) {
                isValid = false;
                break;
            }
            count++;
            isOnBus[person] = true;
        } else if (action == '-') { // hành động ra khỏi xe
            if (!isOnBus[person] || count <= 0) {
                isValid = false;
                break;
            }
            count--;
            isOnBus[person] = false;
        }
    }

    if (isValid && count == 0) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}
