				// זה גורם ל-marked לייצג אותו פעמיים, לכן עלינו לבטל את הייצוג
				code = code.replace(/&amp;(?=[lg]t;)/g, "&");
			}
			else {
				// קוד מרוחק עשוי לכלול תווים שצריך לייצג כדי שיהיו נראים ב-HTML
				code = code.replace(/</g, "&lt;");
			}
