fn sendControllerState(sock: posix.fd_t, addr: *const net.Address, controllerState: []const i16) !void {
    const sockaddr = &addr.any;
    const addrlen = addr.getOsSockLen();
    const bytesToSend = mem.asBytes(controllerState[0..@intFromEnum(ControllerEvents.START)+1]); // ודא שהמטריצה כולה מומרת לבייטים
    const totalBytes = bytesToSend.len; // חשב את מספר הבייטים הכולל שיש לשלוח
    const ret = try posix.sendto(sock, bytesToSend, 0, sockaddr, addrlen);
    std.debug.print("נשלח {x}\n", .{bytesToSend});
    if (ret != totalBytes) {
        std.log.warn("אזהרה: לא כל הנתונים נשלחו. ציפיתי לשלוח {}, אך נשלחו {}\n", .{ totalBytes, ret });
    }
}
