def gen_obstacles(xmax: int, ymax: int) -> Nodelist:
    obstacles = Nodelist()

    def ao(x, y):
        o = Node(x, y)
        obstacles.append(o)

    for _ in range(2):
        ao(randint(-xmax, xmax), randint(-ymax, ymax))

    for y in range(-ymax, ymax):
        ao(0, y + 1)

    for y in range(-ymax, ymax + 1):
        ao(-xmax, y)

    for k, j in zip(range(1, xmax), range(ymax)):
        ao(xmax - k, j - (ymax // 3))

    return obstacles

